(()=>{'use strict';const KEY='toolbox2-reminders-v1';let month=new Date();month.setDate(1);let selected=localDay(new Date()),expanded=false;function localDay(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}function read(){try{const v=JSON.parse(localStorage.getItem(KEY));return Array.isArray(v)?v:[]}catch{return []}}function write(v){try{localStorage.setItem(KEY,JSON.stringify(v))}catch{alert('Unable to save reminders. Check device storage.')}}function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function due(r,date){if(r.date===date)return true;if(!r.repeat||r.repeat==='none'||date<r.date)return false;let a=new Date(r.date+'T12:00:00'),b=new Date(date+'T12:00:00'),days=Math.round((b-a)/86400000);return r.repeat==='daily'||r.repeat==='weekly'&&days%7===0||r.repeat==='monthly'&&a.getDate()===b.getDate()}function done(r,date){return !!(r.doneDates&&r.doneDates.includes(date))}function reminderMarkup(r){let checked=done(r,selected);return `<article class="tr-item ${checked?'tr-done':''}" data-reminder="${esc(r.id)}"><span class="tr-accent ${r.category==='Training'?'tr-training':r.category==='Documents'?'tr-docs':r.category==='Finance'?'tr-finance':''}"></span><div class="tr-copy"><strong>${esc(r.title)}</strong><small>${esc(r.category)}${r.time?' · '+esc(r.time):''}${r.repeat!=='none'?' · '+esc(r.repeat):''}</small>${r.notes?`<p>${esc(r.notes)}</p>`:''}</div><button class="tr-check" data-action="complete" data-id="${esc(r.id)}" aria-label="${checked?'Mark incomplete':'Mark complete'}">${checked?'✓':'○'}</button><div class="tr-actions"><label>Notify me <input type="checkbox" data-action="notify" data-id="${esc(r.id)}" ${r.notify?'checked':''}></label><button data-action="edit" data-id="${esc(r.id)}">Edit</button><button data-action="delete" data-id="${esc(r.id)}">Delete</button></div></article>`}function render(){let host=document.querySelector('#view .resume-section, #view #tr-home');if(!host)return;const list=read(),today=localDay(new Date()),date=new Date(selected+'T12:00:00'),daily=list.filter(r=>due(r,selected)).sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99'));let start=new Date(month.getFullYear(),month.getMonth(),1).getDay(),total=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();let cells='';for(let i=0;i<start;i++)cells+='<span class="tr-blank"></span>';for(let i=1;i<=total;i++){let d=localDay(new Date(month.getFullYear(),month.getMonth(),i)),count=list.filter(r=>due(r,d)&&!done(r,d)).length;cells+=`<button class="tr-day ${d===selected?'selected':''} ${d===today?'today':''}" data-day="${d}" aria-label="${d}, ${count} reminders">${i}${count?'<i></i>':''}</button>`}host.outerHTML=`<section class="tr-home" id="tr-home"><div class="tr-head"><div><h2>Today's Reminders</h2><p>Training, documents and personal plans</p></div><button class="tr-calendar-toggle" id="tr-calendar-toggle" aria-expanded="${expanded}" aria-label="${expanded?'Close':'Open'} reminder calendar">▦</button></div><div class="tr-calendar ${expanded?'tr-open':''}" id="tr-calendar"><div class="tr-month"><button data-month="-1" aria-label="Previous month">‹</button><strong>${new Intl.DateTimeFormat('en-US',{month:'long',year:'numeric'}).format(month)}</strong><button data-month="1" aria-label="Next month">›</button></div><div class="tr-grid">${['S','M','T','W','T','F','S'].map(x=>`<span class="tr-week">${x}</span>`).join('')}${cells}</div></div><div class="tr-dayhead"><div><span>${selected===today?'TODAY':'SCHEDULE'}</span><h3>${new Intl.DateTimeFormat('en-US',{weekday:'long',month:'short',day:'numeric'}).format(date)}</h3></div><button class="tr-add" id="tr-add">+ Add reminder</button></div><div class="tr-list">${daily.length?daily.map(reminderMarkup).join(''):'<p class="tr-empty">No reminders scheduled. Add a task or training session.</p>'}</div><p class="tr-note">Reminders are saved on this device. Notify Me flags items for in-app alerts; background notifications are not yet enabled.</p></section>`}function form(id){let r=read().find(x=>x.id===id)||{title:'',date:selected,time:'',category:'Training',repeat:'none',notes:'',notify:false};let modal=document.getElementById('modal'),content=document.getElementById('modalContent');if(!modal||!content)return;content.innerHTML=`<div class="tr-form"><h2>${id?'Edit':'New'} reminder</h2><form id="tr-form"><label>Reminder title<input name="title" maxlength="100" required value="${esc(r.title)}" placeholder="e.g. Fire drill training"></label><label>Date<input type="date" name="date" required value="${esc(r.date)}"></label><label>Time (optional)<input type="time" name="time" value="${esc(r.time)}"></label><label>Category<select name="category">${['Training','Documents','Finance','Personal','Voyage'].map(c=>`<option ${r.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Repeat<select name="repeat">${['none','daily','weekly','monthly'].map(c=>`<option ${r.repeat===c?'selected':''} value="${c}">${c==='none'?'Does not repeat':c}</option>`).join('')}</select></label><label>Notes<textarea name="notes" rows="2" maxlength="500">${esc(r.notes)}</textarea></label><label class="tr-form-notify"><input type="checkbox" name="notify" ${r.notify?'checked':''}> Notify me (in-app reminder)</label><p class="tr-error" id="tr-error" role="alert"></p><button class="btn full" type="submit">Save reminder</button></form></div>`;modal.showModal();content.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget),title=String(fd.get('title')||'').trim(),date=String(fd.get('date')||'');if(!title||!/^\d{4}-\d{2}-\d{2}$/.test(date)){content.querySelector('#tr-error').textContent='Enter a title and valid date.';return}let list=read(),obj={...r,id:id||'tr-'+Date.now()+'-'+Math.random().toString(36).slice(2,8),title,date,time:String(fd.get('time')||''),category:String(fd.get('category')),repeat:String(fd.get('repeat')),notes:String(fd.get('notes')||'').trim(),notify:fd.has('notify'),doneDates:r.doneDates||[]};if(id)list=list.map(x=>x.id===id?obj:x);else list.push(obj);write(list);selected=date;month=new Date(date+'T12:00:00');month.setDate(1);modal.close();render()})}document.addEventListener('click',e=>{let t=e.target;if(!(t instanceof Element))return;if(t.closest('#tr-calendar-toggle')){e.preventDefault();e.stopPropagation();expanded=!expanded;render();return}let day=t.closest('[data-day]');if(day){selected=day.dataset.day;render();return}let nav=t.closest('[data-month]');if(nav){month.setMonth(month.getMonth()+Number(nav.dataset.month));render();return}if(t.closest('#tr-add')){form();return}let b=t.closest('#tr-home [data-action]');if(!b)return;let id=b.dataset.id,action=b.dataset.action;if(action==='notify')return;let list=read(),r=list.find(x=>x.id===id);if(!r)return;if(action==='edit'){form(id);return}if(action==='delete'){if(!confirm('Delete this reminder?'))return;write(list.filter(x=>x.id!==id));render();return}if(action==='complete'){let ds=new Set(r.doneDates||[]);if(ds.has(selected))ds.delete(selected);else ds.add(selected);r.doneDates=[...ds];write(list);render()}},true);document.addEventListener('change',e=>{let t=e.target;if(!(t instanceof Element)||t.dataset.action!=='notify')return;let list=read(),r=list.find(x=>x.id===t.dataset.id);if(r){r.notify=t.checked;write(list)}});// Home is rebuilt by the base app. Watch for its resume section, including nested updates.
let pending=false;
function schedule(){if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;if(document.querySelector('#view .resume-section'))render()})}
const view=document.getElementById('view');
if(view){new MutationObserver(schedule).observe(view,{childList:true,subtree:true});schedule()}
else document.addEventListener('DOMContentLoaded',()=>{const v=document.getElementById('view');if(v){new MutationObserver(schedule).observe(v,{childList:true,subtree:true});schedule()}});
})();